    def stat_xplore_parse_retry_after(
        value: Optional[str], now: Optional[datetime] = None
    ) -> Optional[float]:
        """Parse ``Retry-After`` (delta-seconds or HTTP-date) into seconds >= 0."""
        if value is None or not str(value).strip():
            return None
        raw = str(value).strip()
        try:
            return max(0.0, float(raw))
        except ValueError:
            pass
        try:
            when = parsedate_to_datetime(raw)
        except (TypeError, ValueError, IndexError, OverflowError):
            return None
        if when is None:
            return None
        if when.tzinfo is None:
            when = when.replace(tzinfo=timezone.utc)
        current = now or datetime.now(timezone.utc)
        return max(0.0, (when - current).total_seconds())


    def _sx_header(headers: Any, name: str) -> Optional[str]:
        if not headers:
            return None
        wanted = name.lower()
        for key, value in dict(headers).items():
            if str(key).lower() == wanted:
                return str(value)
        return None


    def _sx_int_or_none(value: Optional[str]) -> Optional[int]:
        try:
            return int(float(value)) if value is not None else None
        except (TypeError, ValueError):
            return None


    class StatXploreClient:  # pylint: disable=too-many-instance-attributes
        """Serial, paced, retrying client for one Stat-Xplore API key."""

        def __init__(  # pylint: disable=too-many-arguments
            self,
            api_key: str,
            base_url: str = STAT_XPLORE_DEFAULT_BASE_URL,
            *,
            timeout_seconds: float = 120.0,
            min_interval_seconds: float = 2.0,
            max_retries: int = 5,
            retry_max_delay_seconds: float = 60.0,
            rate_limit_reserve: int = 5,
            rate_limit_max_wait_seconds: float = 300.0,
            accept_language: Optional[str] = None,
            session: Any = None,
            sleep: Callable[[float], None] = time.sleep,
            clock: Callable[[], float] = time.monotonic,
            wall_clock: Callable[[], float] = time.time,
            rng: Callable[[], float] = random.random,
        ) -> None:
            if not api_key or not str(api_key).strip():
                raise ValueError("Stat-Xplore 'api_key' connection option is required.")
            parsed = urlsplit(str(base_url or "").strip())
            if (
                parsed.scheme != "https"
                or not parsed.hostname
                or parsed.username
                or parsed.password
                or parsed.query
                or parsed.fragment
            ):
                raise ValueError(
                    "Stat-Xplore 'base_url' must be an https:// service root without "
                    "credentials, query string or fragment."
                )
            if timeout_seconds <= 0 or min_interval_seconds < 0 or max_retries < 0:
                raise ValueError("timeout must be > 0; pacing and retries must be >= 0.")
            if retry_max_delay_seconds < 0 or rate_limit_reserve < 0:
                raise ValueError("retry_max_delay_seconds and rate_limit_reserve must be >= 0.")
            self.base_url = str(base_url).strip().rstrip("/")
            self._origin = (parsed.scheme, (parsed.netloc or "").lower())
            self._api_key = str(api_key).strip()
            self.timeout_seconds = float(timeout_seconds)
            self.min_interval_seconds = float(min_interval_seconds)
            self.max_retries = int(max_retries)
            self.retry_max_delay_seconds = float(retry_max_delay_seconds)
            self.rate_limit_reserve = int(rate_limit_reserve)
            self.rate_limit_max_wait_seconds = float(rate_limit_max_wait_seconds)
            self.accept_language = accept_language or None
            self._session = session
            self._sleep = sleep
            self._clock = clock
            self._wall_clock = wall_clock
            self._rng = rng
            self._next_request_at = 0.0
            self.rate_limit_remaining: Optional[int] = None
            self.rate_limit_reset_ms: Optional[int] = None
            self.stats = {"requests": 0, "retries": 0, "responses_429": 0, "table_requests": 0}

        def __repr__(self) -> str:  # never expose the key
            return f"StatXploreClient(base_url={self.base_url!r})"

        # ------------------------------------------------------------------ helpers

        @property
        def session(self):
            if self._session is None:
                self._session = requests.Session()
            return self._session

        def _headers(self, with_body: bool) -> dict:
            headers = {"APIKey": self._api_key, "Accept": "application/json"}
            if with_body:
                headers["Content-Type"] = "application/json"
            if self.accept_language:
                headers["Accept-Language"] = self.accept_language
            return headers

        def _sanitize(self, text: Any) -> str:
            out = str(text if text is not None else "")
            if self._api_key:
                out = out.replace(self._api_key, "***")
            return out[:_SX_ERROR_SNIPPET_CHARS]

        def _check_origin(self, url: str) -> None:
            parsed = urlsplit(url)
            if (parsed.scheme, (parsed.netloc or "").lower()) != self._origin:
                raise StatXploreResponseError(
                    "Refusing to send the API key to a different origin than base_url "
                    f"({parsed.scheme}://{parsed.netloc})."
                )

        def _backoff(self, attempt: int) -> float:
            base = min(self.retry_max_delay_seconds, float(2 ** attempt))
            return min(self.retry_max_delay_seconds, base * (0.75 + 0.5 * self._rng()))

        def _pace(self) -> None:
            wait = self._next_request_at - self._clock()
            if wait > 0:
                self._sleep(wait)
            self._next_request_at = self._clock() + self.min_interval_seconds

        def _respect_budget(self) -> None:
            remaining = self.rate_limit_remaining
            if remaining is None or remaining > self.rate_limit_reserve:
                return
            reset_ms = self.rate_limit_reset_ms
            wait = (reset_ms / 1000.0 - self._wall_clock()) if reset_ms else None
            if wait is not None and wait <= 0:
                self.rate_limit_remaining = None
                return
            if wait is not None and wait <= self.rate_limit_max_wait_seconds:
                self._sleep(wait)
                self.rate_limit_remaining = None
                return
            raise StatXploreRateLimitError(
                f"Stat-Xplore hourly request budget is down to {remaining} (reserve "
                f"{self.rate_limit_reserve}); the limit resets at epoch ms {reset_ms}. "
                "No checkpoint was advanced - rerun after the reset.",
                status_code=429,
            )

        def _record_rate_headers(self, headers: Any) -> None:
            remaining = _sx_int_or_none(_sx_header(headers, "X-RateLimit-Remaining"))
            reset = _sx_int_or_none(_sx_header(headers, "X-RateLimit-Reset"))
            if remaining is not None:
                self.rate_limit_remaining = remaining
            if reset is not None:
                self.rate_limit_reset_ms = reset

        def _error_detail(self, response: Any) -> str:
            try:
                body = response.json()
            except ValueError:
                return ""
            if isinstance(body, dict):
                parts = [str(body.get(k)) for k in ("errorType", "message") if body.get(k)]
                return self._sanitize(": ".join(parts))
            return ""

        # ------------------------------------------------------------------ core

        def request_json(
            self, method: str, url: str, body: Optional[dict] = None
        ) -> tuple[Any, Any]:
            """Issue one logical request with bounded retries. Returns (json, response)."""
            self._check_origin(url)
            path = urlsplit(url).path
            label = f"{method} {path}"
            for attempt in range(self.max_retries + 1):
                self._respect_budget()
                self._pace()
                self.stats["requests"] += 1
                try:
                    response = self.session.request(
                        method,
                        url,
                        headers=self._headers(body is not None),
                        json=body,
                        timeout=self.timeout_seconds,
                    )
                except (requests.ConnectionError, requests.Timeout,
                        requests.exceptions.ChunkedEncodingError) as exc:
                    if attempt >= self.max_retries:
                        raise StatXploreError(
                            f"Stat-Xplore {label}: network failure after {attempt + 1} "
                            f"attempt(s) ({type(exc).__name__})."
                        ) from None
                    self.stats["retries"] += 1
                    self._sleep(self._backoff(attempt))
                    continue

                self._record_rate_headers(response.headers)
                status = int(response.status_code)
                if status in STAT_XPLORE_RETRIABLE_STATUS:
                    if status == 429:
                        self.stats["responses_429"] += 1
                    if attempt >= self.max_retries:
                        cls = StatXploreRateLimitError if status == 429 else StatXploreError
                        raise cls(
                            f"Stat-Xplore {label}: HTTP {status} persisted after "
                            f"{attempt + 1} attempt(s). {self._error_detail(response)}".strip(),
                            status_code=status,
                        )
                    delay = stat_xplore_parse_retry_after(_sx_header(response.headers, "Retry-After"))
                    if delay is None:
                        delay = self._backoff(attempt)
                    self.stats["retries"] += 1
                    self._sleep(min(delay, self.retry_max_delay_seconds))
                    continue
                if status in (401, 403):
                    raise StatXploreAuthError(
                        f"Stat-Xplore {label}: HTTP {status} - API key rejected or no access. "
                        f"{self._error_detail(response)}".strip(),
                        status_code=status,
                    )
                if status >= 400:
                    raise StatXploreError(
                        f"Stat-Xplore {label}: HTTP {status}. {self._error_detail(response)}".strip(),
                        status_code=status,
                    )
                try:
                    data = response.json()
                except ValueError:
                    raise StatXploreResponseError(
                        f"Stat-Xplore {label}: HTTP {status} response was not valid JSON.",
                        status_code=status,
                    ) from None
                return data, response
            raise StatXploreError(f"Stat-Xplore {label}: retries exhausted.")  # pragma: no cover

        def _get_object(self, url: str) -> tuple[dict, Any]:
            data, response = self.request_json("GET", url)
            if not isinstance(data, dict):
                raise StatXploreResponseError(f"Stat-Xplore GET {urlsplit(url).path}: expected a JSON object.")
            return data, response

        # ------------------------------------------------------------------ endpoints

        def schema_url(self, item_id: Optional[str] = None) -> str:
            if not item_id:
                return f"{self.base_url}/schema"
            return f"{self.base_url}/schema/{quote(str(item_id), safe='')}"

        def get_schema(self, item_id: Optional[str] = None) -> dict:
            """GET /schema[/{id}], following ``Link rel=next`` pagination of children."""
            url = self.schema_url(item_id)
            first, response = self._get_object(url)
            children = list(first.get("children") or [])
            pages = 1
            next_url = (getattr(response, "links", None) or {}).get("next", {}).get("url")
            while next_url:
                pages += 1
                if pages > _SX_MAX_SCHEMA_PAGES:
                    raise StatXploreResponseError(
                        f"Stat-Xplore schema item {item_id!r} exceeded {_SX_MAX_SCHEMA_PAGES} pages."
                    )
                page, response = self._get_object(next_url)
                page_children = page.get("children")
                if not isinstance(page_children, list):
                    raise StatXploreResponseError(
                        f"Stat-Xplore schema item {item_id!r}: paginated page without 'children'."
                    )
                children.extend(page_children)
                next_url = (getattr(response, "links", None) or {}).get("next", {}).get("url")
            if "children" in first or pages > 1:
                first = dict(first)
                first["children"] = children
            return first

        def get_info(self) -> dict:
            return self._get_object(f"{self.base_url}/info")[0]

        def get_rate_limit(self) -> dict:
            return self._get_object(f"{self.base_url}/rate_limit")[0]

        def post_table(self, query: dict) -> dict:
            """POST /table. Returns the decoded response object."""
            self.stats["table_requests"] += 1
            data, _ = self.request_json("POST", f"{self.base_url}/table", body=query)
            if not isinstance(data, dict):
                raise StatXploreResponseError("Stat-Xplore POST /table: expected a JSON object.")
            return data


    ########################################################
    # src/databricks/labs/community_connector/sources/stat_xplore/stat_xplore_config.py
    ########################################################

    STAT_XPLORE_QUERY_OPTION_KEYS = (
        "database",
        "measures",
        "dimensions",
        "recodes",
        "time_field",
        "periods",
        "latest_periods",
        "period_batch_size",
        "ingestion_mode",
        "lookback_periods",
        "max_periods_per_batch",
        "max_cells_per_request",
        "output",
    )
    STAT_XPLORE_INGESTION_MODES = ("snapshot", "incremental")
    STAT_XPLORE_OUTPUTS = ("cells", "responses")

    _SX_DEFAULT_PERIOD_BATCH_SIZE = 1
    _SX_DEFAULT_LOOKBACK_PERIODS = 2
    _SX_DEFAULT_MAX_PERIODS_PER_BATCH = 12
    _SX_DEFAULT_MAX_CELLS_PER_REQUEST = 250_000
    _SX_HARD_MAX_CELLS_PER_REQUEST = 5_000_000


    def stat_xplore_canonical_json(value: Any) -> str:
        """Deterministic JSON used for hashing and for persisted request JSON."""
        return json.dumps(value, sort_keys=True, separators=(",", ":"), ensure_ascii=False)


    def stat_xplore_sha256(value: Any) -> str:
        text = value if isinstance(value, str) else stat_xplore_canonical_json(value)
        return hashlib.sha256(text.encode("utf-8")).hexdigest()


    def _sx_json(value: Any, name: str) -> Any:
        if isinstance(value, str):
            try:
                return json.loads(value)
            except json.JSONDecodeError as exc:
                raise ValueError(f"Stat-Xplore option '{name}' is not valid JSON: {exc.msg}") from None
        return value


    def stat_xplore_int_option(
        value: Any, name: str, default: Optional[int], minimum: int = 0,
        maximum: Optional[int] = None,
    ) -> Optional[int]:
        if value is None or (isinstance(value, str) and not value.strip()):
            return default
        try:
            if isinstance(value, bool):
                raise ValueError
            parsed = int(str(value).strip())
        except ValueError:
            raise ValueError(f"Stat-Xplore option '{name}' must be an integer, got {value!r}.") from None
        if parsed < minimum or (maximum is not None and parsed > maximum):
            bound = f">= {minimum}" + (f" and <= {maximum}" if maximum is not None else "")
            raise ValueError(f"Stat-Xplore option '{name}' must be {bound}, got {parsed}.")
        return parsed


    def stat_xplore_float_option(value: Any, name: str, default: float, minimum: float = 0.0) -> float:
        if value is None or (isinstance(value, str) and not value.strip()):
            return default
        try:
            parsed = float(str(value).strip())
        except ValueError:
            raise ValueError(f"Stat-Xplore option '{name}' must be a number, got {value!r}.") from None
        if parsed < minimum:
            raise ValueError(f"Stat-Xplore option '{name}' must be >= {minimum}, got {parsed}.")
        return parsed


    def _sx_require_id(value: Any, name: str, prefix: str) -> str:
        if not isinstance(value, str) or not value.startswith(prefix) or len(value) <= len(prefix):
            raise ValueError(
                f"Stat-Xplore option '{name}' must be a Stat-Xplore ID starting with "
                f"'{prefix}' (as returned by /schema), got {value!r}."
            )
        return value


    def _sx_parse_measures(raw: Any) -> list:
        value = _sx_json(raw, "measures")
        if isinstance(value, str):
            value = [value]
        if not isinstance(value, list) or not value:
            raise ValueError("Stat-Xplore option 'measures' must be a non-empty JSON array of measure IDs.")
        out = [_sx_require_id(m, "measures", "str:") for m in value]
        if len(set(out)) != len(out):
            raise ValueError("Stat-Xplore option 'measures' contains duplicates.")
        return out


    def _sx_parse_dimensions(raw: Any) -> list:
        value = _sx_json(raw, "dimensions")
        if not isinstance(value, list) or not value:
            raise ValueError(
                "Stat-Xplore option 'dimensions' must be a non-empty JSON array of field-ID "
                'arrays, e.g. [["str:field:...:A"],["str:field:...:B"]].'
            )
        dims = []
        for dim in value:
            fields = [dim] if isinstance(dim, str) else dim
            if not isinstance(fields, list) or not fields:
                raise ValueError("Each Stat-Xplore dimension must be a field ID or a non-empty array of field IDs.")
            dims.append([_sx_require_id(f, "dimensions", "str:field:") for f in fields])
        flat = [f for d in dims for f in d]
        if len(set(flat)) != len(flat):
            raise ValueError("Stat-Xplore option 'dimensions' lists the same field more than once.")
        return dims


    def _sx_parse_recodes(raw: Any, dimension_fields: list) -> dict:
        if raw is None or (isinstance(raw, str) and not raw.strip()):
            return {}
        value = _sx_json(raw, "recodes")
        if not isinstance(value, dict):
            raise ValueError("Stat-Xplore option 'recodes' must be a JSON object keyed by field ID.")
        out = {}
        for field_id, recode in value.items():
            _sx_require_id(field_id, "recodes", "str:field:")
            if field_id not in dimension_fields:
                raise ValueError(f"Stat-Xplore recode field {field_id!r} is not in 'dimensions'.")
            if not isinstance(recode, dict) or set(recode) - {"map", "total"}:
                raise ValueError(f"Stat-Xplore recode for {field_id!r} may only contain 'map' and 'total'.")
            clean = {}
            if "map" in recode:
                groups = recode["map"]
                if not isinstance(groups, list) or not groups:
                    raise ValueError(f"Stat-Xplore recode map for {field_id!r} must be a non-empty array.")
                clean_groups = []
                for group in groups:
                    members = [group] if isinstance(group, str) else group
                    if not isinstance(members, list) or not members:
                        raise ValueError(f"Stat-Xplore recode map for {field_id!r} has an empty group.")
                    clean_groups.append([_sx_require_id(v, "recodes", "str:value:") for v in members])
                clean["map"] = clean_groups
            if "total" in recode:
                if not isinstance(recode["total"], bool):
                    raise ValueError(f"Stat-Xplore recode 'total' for {field_id!r} must be true or false.")
                clean["total"] = recode["total"]
            out[field_id] = clean
        return out


    def _sx_parse_periods(raw: Any) -> Optional[list]:
        if raw is None or (isinstance(raw, str) and not raw.strip()):
            return None
        value = _sx_json(raw, "periods")
        if not isinstance(value, list) or not value:
            raise ValueError("Stat-Xplore option 'periods' must be a non-empty JSON array of time value IDs.")
        out = [_sx_require_id(p, "periods", "str:value:") for p in value]
        if len(set(out)) != len(out):
            raise ValueError("Stat-Xplore option 'periods' contains duplicates.")
        return out


    @dataclass(frozen=True)
    class StatXploreQueryConfig:  # pylint: disable=too-many-instance-attributes
        """Validated definition of one statistical query table."""

        table_name: str
        database: str
        measures: list
        dimensions: list
        recodes: dict = field(default_factory=dict)
        time_field: Optional[str] = None
        periods: Optional[list] = None
        latest_periods: Optional[int] = None
        period_batch_size: int = _SX_DEFAULT_PERIOD_BATCH_SIZE
        ingestion_mode: str = "snapshot"
        lookback_periods: int = _SX_DEFAULT_LOOKBACK_PERIODS
        max_periods_per_batch: int = _SX_DEFAULT_MAX_PERIODS_PER_BATCH
        max_cells_per_request: int = _SX_DEFAULT_MAX_CELLS_PER_REQUEST
        output: str = "cells"

        @property
        def incremental(self) -> bool:
            return self.ingestion_mode == "incremental"

        @property
        def connector_manages_periods(self) -> bool:
            """True when the connector recodes the time field per request."""
            return bool(self.time_field) and self.time_field not in self.recodes

        def base_query(self) -> dict:
            query = {
                "database": self.database,
                "measures": list(self.measures),
                "dimensions": [list(d) for d in self.dimensions],
            }
            if self.recodes:
                query["recodes"] = json.loads(stat_xplore_canonical_json(self.recodes))
            return query

        @property
        def query_hash(self) -> str:
            """Stable identity of the statistical definition (excludes period selection)."""
            return stat_xplore_sha256({"query": self.base_query(), "time_field": self.time_field})

        def build_query(self, period_uris: Optional[list] = None) -> dict:
            query = self.base_query()
            if period_uris is not None:
                if not self.connector_manages_periods:
                    raise ValueError("build_query(period_uris) requires a connector-managed time_field.")
                recodes = dict(query.get("recodes") or {})
                recodes[self.time_field] = {"map": [[p] for p in period_uris], "total": False}
                query["recodes"] = recodes
            return query

        def period_discovery_query(self) -> dict:
            """Smallest /table query that returns the full, un-recoded time axis."""
            return {
                "database": self.database,
                "measures": [self.measures[0]],
                "dimensions": [[self.time_field]],
            }

        def estimated_cells(self, period_count: Optional[int] = None) -> Optional[int]:
            """Upper-bound cell count if every field's cardinality is known, else None."""
            total = len(self.measures)
            for dim in self.dimensions:
                for field_id in dim:
                    recode = self.recodes.get(field_id) or {}
                    if field_id == self.time_field and period_count is not None:
                        size = period_count
                    elif "map" in recode:
                        size = len(recode["map"]) + (1 if recode.get("total") else 0)
                    else:
                        return None
                    total *= size
            return total


    def stat_xplore_parse_query_config(table_name: str, raw: dict) -> StatXploreQueryConfig:
        """Validate a raw (registry or table_options) definition."""
        unknown = sorted(set(raw) - set(STAT_XPLORE_QUERY_OPTION_KEYS))
        if unknown:
            raise ValueError(f"Stat-Xplore table '{table_name}': unknown query option(s) {unknown}.")
        if not raw.get("database"):
            raise ValueError(f"Stat-Xplore table '{table_name}': 'database' is required.")
        database = _sx_require_id(raw.get("database"), "database", "str:database:")
        measures = _sx_parse_measures(raw.get("measures"))
        dimensions = _sx_parse_dimensions(raw.get("dimensions"))
        flat_fields = [f for d in dimensions for f in d]
        recodes = _sx_parse_recodes(raw.get("recodes"), flat_fields)

        time_field = raw.get("time_field") or None
        if time_field is not None:
            _sx_require_id(time_field, "time_field", "str:field:")
            if [time_field] not in dimensions:
                raise ValueError(
                    f"Stat-Xplore table '{table_name}': time_field must appear in 'dimensions' "
                    "as its own single-field dimension."
                )

        ingestion_mode = str(raw.get("ingestion_mode") or "snapshot").strip().lower()
        if ingestion_mode not in STAT_XPLORE_INGESTION_MODES:
            raise ValueError(f"Stat-Xplore 'ingestion_mode' must be one of {STAT_XPLORE_INGESTION_MODES}.")
        output = str(raw.get("output") or "cells").strip().lower()
        if output not in STAT_XPLORE_OUTPUTS:
            raise ValueError(f"Stat-Xplore 'output' must be one of {STAT_XPLORE_OUTPUTS}.")

        periods = _sx_parse_periods(raw.get("periods"))
        latest_periods = stat_xplore_int_option(raw.get("latest_periods"), "latest_periods", None, 1)
        if periods and latest_periods:
            raise ValueError("Stat-Xplore options 'periods' and 'latest_periods' are mutually exclusive.")
        managed = bool(time_field) and time_field not in recodes
        if (periods or latest_periods or ingestion_mode == "incremental") and not managed:
            raise ValueError(
                f"Stat-Xplore table '{table_name}': 'periods', 'latest_periods' and "
                "ingestion_mode=incremental need a 'time_field' that is NOT also recoded "
                "in 'recodes' (the connector recodes it per request)."
            )
        if ingestion_mode == "incremental" and periods:
            raise ValueError("Stat-Xplore incremental tables discover periods; do not set 'periods'.")

        return StatXploreQueryConfig(
            table_name=table_name,
            database=database,
            measures=measures,
            dimensions=dimensions,
            recodes=recodes,
            time_field=time_field,
            periods=periods,
            latest_periods=latest_periods,
            period_batch_size=stat_xplore_int_option(
                raw.get("period_batch_size"), "period_batch_size", _SX_DEFAULT_PERIOD_BATCH_SIZE, 1, 120
            ),
            ingestion_mode=ingestion_mode,
            lookback_periods=stat_xplore_int_option(
                raw.get("lookback_periods"), "lookback_periods", _SX_DEFAULT_LOOKBACK_PERIODS, 0, 120
            ),
            max_periods_per_batch=stat_xplore_int_option(
                raw.get("max_periods_per_batch"), "max_periods_per_batch",
                _SX_DEFAULT_MAX_PERIODS_PER_BATCH, 1, 1000,
            ),
            max_cells_per_request=stat_xplore_int_option(
                raw.get("max_cells_per_request"), "max_cells_per_request",
                _SX_DEFAULT_MAX_CELLS_PER_REQUEST, 1, _SX_HARD_MAX_CELLS_PER_REQUEST,
            ),
            output=output,
        )


    def stat_xplore_parse_registry(raw: Any, reserved_names: tuple) -> dict:
        """Parse the connection-level ``table_registry`` JSON into validated configs."""
        if raw is None or (isinstance(raw, str) and not raw.strip()):
            return {}
        value = _sx_json(raw, "table_registry")
        if not isinstance(value, dict):
            raise ValueError("Stat-Xplore 'table_registry' must be a JSON object of table_name -> query.")
        out = {}
        for name, definition in value.items():
            if not isinstance(name, str) or not name.strip() or name.startswith("_community_"):
                raise ValueError(f"Invalid Stat-Xplore registry table name {name!r}.")
            if name in reserved_names:
                raise ValueError(f"Stat-Xplore registry table name {name!r} clashes with a built-in table.")
            if not isinstance(definition, dict):
                raise ValueError(f"Stat-Xplore registry entry {name!r} must be a JSON object.")
            stat_xplore_parse_query_config(name, definition)  # validate eagerly
            out[name] = dict(definition)
        return out


    ########################################################
    # src/databricks/labs/community_connector/sources/stat_xplore/stat_xplore_cube.py
    ########################################################

    def stat_xplore_classify_value(value: Any) -> tuple:
        """Return ``(numeric_value_or_None, status)`` without inventing zeros."""
        if value is None:
            return None, "missing"
        if isinstance(value, bool):
            return None, "non_numeric"
        if isinstance(value, (int, float)) and math.isfinite(float(value)):
            return float(value), "numeric"
        return None, "non_numeric"


    def stat_xplore_period_code(uri: Optional[str]) -> Optional[str]:
        """Trailing code of a value URI, e.g. ``...:C_UC_DATE:202605`` -> ``202605``."""
        if not uri:
            return None
        return str(uri).rsplit(":", 1)[-1]


    def _sx_list(obj: Any, key: str, where: str) -> list:
        value = obj.get(key) if isinstance(obj, dict) else None
        if not isinstance(value, list):
            raise StatXploreResponseError(f"Stat-Xplore /table response: missing list '{key}' in {where}.")
        return value


    def _sx_check_shape(values: Any, sizes: list, measure: str, level: int = 0) -> None:
        if level == len(sizes):
            if isinstance(values, list):
                raise StatXploreResponseError(
                    f"Stat-Xplore cube {measure!r}: values nested deeper than the {len(sizes)} fields."
                )
            return
        if not isinstance(values, list) or len(values) != sizes[level]:
            got = len(values) if isinstance(values, list) else type(values).__name__
            raise StatXploreResponseError(
                f"Stat-Xplore cube {measure!r}: level {level} has {got} entries, "
                f"expected {sizes[level]} (field item count). Response is incomplete or malformed."
            )
        for child in values:
            _sx_check_shape(child, sizes, measure, level + 1)


    def stat_xplore_validate_table_response(
        response: dict, config: StatXploreQueryConfig
    ) -> tuple:
        """Validate a /table response. Returns ``(fields, cubes, measure_labels)``."""
        if not isinstance(response, dict):
            raise StatXploreResponseError("Stat-Xplore /table response is not a JSON object.")
        fields = _sx_list(response, "fields", "response")
        cubes = response.get("cubes")
        if not isinstance(cubes, dict):
            raise StatXploreResponseError("Stat-Xplore /table response: missing object 'cubes'.")

        expected_fields = [f for dim in config.dimensions for f in dim]
        returned_fields = []
        for i, fld in enumerate(fields):
            if not isinstance(fld, dict) or not isinstance(fld.get("uri"), str):
                raise StatXploreResponseError(f"Stat-Xplore /table response: field #{i} has no 'uri'.")
            for j, item in enumerate(_sx_list(fld, "items", f"field {fld['uri']!r}")):
                if not isinstance(item, dict) or not isinstance(item.get("uris", []), list):
                    raise StatXploreResponseError(
                        f"Stat-Xplore /table response: item #{j} of field {fld['uri']!r} is malformed."
                    )
            returned_fields.append(fld["uri"])
        if sorted(returned_fields) != sorted(expected_fields):
            raise StatXploreResponseError(
                "Stat-Xplore /table response fields do not match the requested dimensions "
                f"(requested {expected_fields}, returned {returned_fields})."
            )

        sizes = [len(f["items"]) for f in fields]
        cells_per_measure = 1
        for size in sizes:
            cells_per_measure *= size
        total_cells = cells_per_measure * len(config.measures)
        if total_cells > config.max_cells_per_request:
            raise StatXploreResponseError(
                f"Stat-Xplore table '{config.table_name}': response has {total_cells} cells, above "
                f"max_cells_per_request={config.max_cells_per_request}. Narrow the query with "
                "recodes or a smaller period_batch_size."
            )

        missing = [m for m in config.measures if m not in cubes]
        if missing:
            raise StatXploreResponseError(f"Stat-Xplore /table response has no cube for measure(s) {missing}.")
        for measure in config.measures:
            cube = cubes[measure]
            if not isinstance(cube, dict) or "values" not in cube:
                raise StatXploreResponseError(f"Stat-Xplore cube {measure!r} has no 'values'.")
            _sx_check_shape(cube["values"], sizes, measure)

        labels = {}
        for measure in response.get("measures") or []:
            if isinstance(measure, dict) and measure.get("uri"):
                labels[measure["uri"]] = measure.get("label")
        return fields, cubes, labels


    def _sx_iter_coords(sizes: list):
        if not sizes:
            yield ()
            return
        for i in range(sizes[0]):
            for rest in _sx_iter_coords(sizes[1:]):
                yield (i,) + rest


    def _sx_cell(values: Any, coords: tuple) -> Any:
        for idx in coords:
            values = values[idx]
        return values


    def _sx_annotation_map(response: dict) -> dict:
        raw = response.get("annotationMap")
        return raw if isinstance(raw, dict) else {}


    def _sx_keys(obj: Any) -> list:
        keys = obj.get("annotationKeys") if isinstance(obj, dict) else None
        return [str(k) for k in keys] if isinstance(keys, list) else []


    def stat_xplore_response_stats(response: dict, config: StatXploreQueryConfig) -> dict:
        """Cell counts by value status for an already-validated response."""
        fields = response["fields"]
        sizes = [len(f["items"]) for f in fields]
        counts = {"numeric": 0, "missing": 0, "non_numeric": 0}
        for measure in config.measures:
            values = response["cubes"][measure]["values"]
            for coords in _sx_iter_coords(sizes):
                counts[stat_xplore_classify_value(_sx_cell(values, coords))[1]] += 1
        return counts


    def stat_xplore_cell_records(  # pylint: disable=too-many-locals
        response: dict,
        config: StatXploreQueryConfig,
        request_query: dict,
        retrieved_at: str,
    ) -> list:
        """Flatten a validated response into one record per (measure, cell)."""
        fields, cubes, measure_labels = stat_xplore_validate_table_response(response, config)
        response_sha = stat_xplore_sha256(response)
        request_json = stat_xplore_canonical_json(request_query)
        annotation_map = _sx_annotation_map(response)
        database = response.get("database") if isinstance(response.get("database"), dict) else {}
        database_id = database.get("id") or config.database
        database_keys = _sx_keys(database)
        sizes = [len(f["items"]) for f in fields]
        time_idx = next(
            (i for i, f in enumerate(fields) if config.time_field and f["uri"] == config.time_field), None
        )

        records = []
        for measure in config.measures:
            cube = cubes[measure]
            cube_meta = stat_xplore_canonical_json({k: v for k, v in cube.items() if k != "values"})
            for coords in _sx_iter_coords(sizes):
                raw = _sx_cell(cube["values"], coords)
                value, status = stat_xplore_classify_value(raw)
                dims = []
                keys = list(database_keys)
                for fld, idx in zip(fields, coords):
                    item = fld["items"][idx]
                    item_keys = _sx_keys(item)
                    keys.extend(_sx_keys(fld) + item_keys)
                    dims.append({
                        "field_uri": fld["uri"],
                        "field_label": fld.get("label"),
                        "item_index": idx,
                        "item_type": item.get("type"),
                        "item_uris": [str(u) for u in item.get("uris") or []],
                        "item_labels": [str(lbl) for lbl in item.get("labels") or []],
                        "annotation_keys": item_keys,
                    })
                identity = [config.query_hash, measure, [[d["field_uri"], d["item_uris"]] for d in dims]]
                if any(not d["item_uris"] for d in dims):
                    # Items without URIs (e.g. totals) are identified by position+label.
                    identity.append([[d["item_index"], d["item_labels"]] for d in dims])
                keys = sorted(set(keys))
                period = dims[time_idx] if time_idx is not None else None
                period_uri = period["item_uris"][0] if period and period["item_uris"] else None
                records.append({
                    "record_id": stat_xplore_sha256(identity),
                    "table_name": config.table_name,
                    "query_hash": config.query_hash,
                    "database_id": database_id,
                    "measure_uri": measure,
                    "measure_label": measure_labels.get(measure),
                    "dimensions": dims,
                    "dimension_key": "|".join(
                        f"{d['field_uri']}={','.join(d['item_uris']) or '#' + str(d['item_index'])}"
                        for d in dims
                    ),
                    "period_field_uri": config.time_field,
                    "period_uri": period_uri,
                    "period_code": stat_xplore_period_code(period_uri),
                    "period_label": (period["item_labels"] or [None])[0] if period else None,
                    "value": value,
                    "value_raw": json.dumps(raw, ensure_ascii=False),
                    "value_status": status,
                    "annotation_keys": keys,
                    "annotations_json": stat_xplore_canonical_json(
                        {k: annotation_map[k] for k in keys if k in annotation_map}
                    ),
                    "cube_metadata_json": cube_meta,
                    "request_json": request_json,
                    "response_sha256": response_sha,
                    "retrieved_at": retrieved_at,
                })
        return records


    def stat_xplore_response_record(
        response: dict,
        config: StatXploreQueryConfig,
        request_query: dict,
        period_uris: Optional[list],
        retrieved_at: str,
    ) -> dict:
        """One Bronze row holding the complete, unmodified /table response."""
        stat_xplore_validate_table_response(response, config)
        counts = stat_xplore_response_stats(response, config)
        database = response.get("database") if isinstance(response.get("database"), dict) else {}
        periods = list(period_uris or [])
        return {
            "response_id": stat_xplore_sha256([config.query_hash, periods]),
            "table_name": config.table_name,
            "query_hash": config.query_hash,
            "database_id": database.get("id") or config.database,
            "measure_uris": list(config.measures),
            "period_field_uri": config.time_field,
            "period_uris": periods,
            "request_json": stat_xplore_canonical_json(request_query),
            "response_json": json.dumps(response, ensure_ascii=False, sort_keys=True),
            "response_sha256": stat_xplore_sha256(response),
            "cell_count": sum(counts.values()),
            "numeric_cell_count": counts["numeric"],
            "missing_cell_count": counts["missing"],
            "non_numeric_cell_count": counts["non_numeric"],
            "retrieved_at": retrieved_at,
        }


    ########################################################
    # src/databricks/labs/community_connector/sources/stat_xplore/stat_xplore_schemas.py
    ########################################################

    STAT_XPLORE_TABLE_SCHEMA_ITEMS = "schema_items"
    STAT_XPLORE_TABLE_INFO = "info"
    STAT_XPLORE_TABLE_RATE_LIMIT = "rate_limit"
    STAT_XPLORE_BUILTIN_TABLES = (
        STAT_XPLORE_TABLE_SCHEMA_ITEMS,
        STAT_XPLORE_TABLE_INFO,
        STAT_XPLORE_TABLE_RATE_LIMIT,
    )

    STAT_XPLORE_SCHEMA_ITEMS_SCHEMA = StructType([
        StructField("id", StringType(), False),
        StructField("parent_id", StringType(), False),
        StructField("label", StringType(), True),
        StructField("type", StringType(), True),
        StructField("location", StringType(), True),
        StructField("depth", IntegerType(), False),
        StructField("is_expanded", BooleanType(), False),
        StructField("child_count", IntegerType(), True),
        StructField("schema_root", StringType(), False),
        StructField("raw_json", StringType(), False),
        StructField("retrieved_at", TimestampType(), False),
    ])

    STAT_XPLORE_INFO_SCHEMA = StructType([
        StructField("locale", StringType(), False),
        StructField("display_name", StringType(), True),
        StructField("raw_json", StringType(), False),
        StructField("retrieved_at", TimestampType(), False),
    ])

    STAT_XPLORE_RATE_LIMIT_SCHEMA = StructType([
        StructField("scope", StringType(), False),
        StructField("limit", LongType(), True),
        StructField("remaining", LongType(), True),
        StructField("reset_epoch_ms", LongType(), True),
        StructField("raw_json", StringType(), False),
        StructField("retrieved_at", TimestampType(), False),
    ])

    _SX_DIMENSION_STRUCT = StructType([
        StructField("field_uri", StringType(), False),
        StructField("field_label", StringType(), True),
        StructField("item_index", IntegerType(), False),
        StructField("item_type", StringType(), True),
        StructField("item_uris", ArrayType(StringType()), False),
        StructField("item_labels", ArrayType(StringType()), False),
        StructField("annotation_keys", ArrayType(StringType()), False),
    ])

    STAT_XPLORE_CELLS_SCHEMA = StructType([
        StructField("record_id", StringType(), False),
        StructField("table_name", StringType(), False),
        StructField("query_hash", StringType(), False),
        StructField("database_id", StringType(), False),
        StructField("measure_uri", StringType(), False),
        StructField("measure_label", StringType(), True),
        StructField("dimensions", ArrayType(_SX_DIMENSION_STRUCT), False),
        StructField("dimension_key", StringType(), False),
        StructField("period_field_uri", StringType(), True),
        StructField("period_uri", StringType(), True),
        StructField("period_code", StringType(), True),
        StructField("period_label", StringType(), True),
        StructField("value", DoubleType(), True),
        StructField("value_raw", StringType(), False),
        StructField("value_status", StringType(), False),
        StructField("annotation_keys", ArrayType(StringType()), False),
        StructField("annotations_json", StringType(), False),
        StructField("cube_metadata_json", StringType(), False),
        StructField("request_json", StringType(), False),
        StructField("response_sha256", StringType(), False),
        StructField("retrieved_at", TimestampType(), False),
    ])

    STAT_XPLORE_RESPONSES_SCHEMA = StructType([
        StructField("response_id", StringType(), False),
        StructField("table_name", StringType(), False),
        StructField("query_hash", StringType(), False),
        StructField("database_id", StringType(), False),
        StructField("measure_uris", ArrayType(StringType()), False),
        StructField("period_field_uri", StringType(), True),
        StructField("period_uris", ArrayType(StringType()), False),
        StructField("request_json", StringType(), False),
        StructField("response_json", StringType(), False),
        StructField("response_sha256", StringType(), False),
        StructField("cell_count", LongType(), False),
        StructField("numeric_cell_count", LongType(), False),
        StructField("missing_cell_count", LongType(), False),
        StructField("non_numeric_cell_count", LongType(), False),
        StructField("retrieved_at", TimestampType(), False),
    ])

    STAT_XPLORE_BUILTIN_SCHEMAS = {
        STAT_XPLORE_TABLE_SCHEMA_ITEMS: STAT_XPLORE_SCHEMA_ITEMS_SCHEMA,
        STAT_XPLORE_TABLE_INFO: STAT_XPLORE_INFO_SCHEMA,
        STAT_XPLORE_TABLE_RATE_LIMIT: STAT_XPLORE_RATE_LIMIT_SCHEMA,
    }

    STAT_XPLORE_BUILTIN_METADATA = {
        STAT_XPLORE_TABLE_SCHEMA_ITEMS: {"primary_keys": ["id", "parent_id"], "ingestion_type": "snapshot"},
        STAT_XPLORE_TABLE_INFO: {"primary_keys": ["locale"], "ingestion_type": "snapshot"},
        STAT_XPLORE_TABLE_RATE_LIMIT: {"primary_keys": ["scope"], "ingestion_type": "snapshot"},
    }

    STAT_XPLORE_SCHEMA_OPTION_KEYS = (
        "schema_root",
        "schema_expand_types",
        "schema_max_depth",
        "schema_max_requests",
    )


    ########################################################
    # src/databricks/labs/community_connector/sources/stat_xplore/stat_xplore.py
    ########################################################

    _SX_DEFAULT_SCHEMA_ROOT = "str:folder:root"
    _SX_DEFAULT_EXPAND_TYPES = "FOLDER"


    class StatXploreLakeflowConnect(LakeflowConnect):  # pylint: disable=too-many-instance-attributes
        """LakeflowConnect implementation for DWP Stat-Xplore."""

        def __init__(self, options: dict[str, str]) -> None:
            super().__init__(options)
            api_key = options.get("api_key")
            if not api_key or not str(api_key).strip():
                raise ValueError(
                    "Stat-Xplore connection option 'api_key' is required (sent as the APIKey header)."
                )
            self._api_key = str(api_key).strip()
            self._base_url = (options.get("base_url") or STAT_XPLORE_DEFAULT_BASE_URL).strip()
            self._client_kwargs = {
                "timeout_seconds": stat_xplore_float_option(
                    options.get("timeout_seconds"), "timeout_seconds", 120.0, 1.0),
                "min_interval_seconds": stat_xplore_float_option(
                    options.get("min_request_interval_seconds"), "min_request_interval_seconds", 2.0),
                "max_retries": stat_xplore_int_option(
                    options.get("max_retries"), "max_retries", 5, 0, 10),
                "retry_max_delay_seconds": stat_xplore_float_option(
                    options.get("retry_max_delay_seconds"), "retry_max_delay_seconds", 60.0),
                "rate_limit_reserve": stat_xplore_int_option(
                    options.get("rate_limit_reserve"), "rate_limit_reserve", 25, 0, 1999),
                "rate_limit_max_wait_seconds": stat_xplore_float_option(
                    options.get("rate_limit_max_wait_seconds"), "rate_limit_max_wait_seconds", 300.0),
                "accept_language": (options.get("accept_language") or "").strip() or None,
            }
            self._max_table_requests = stat_xplore_int_option(
                options.get("max_table_requests_per_run"), "max_table_requests_per_run", 200, 1, 2000)
            self._registry = stat_xplore_parse_registry(
                options.get("table_registry"), STAT_XPLORE_BUILTIN_TABLES)
            # Validate the client settings (base_url etc.) eagerly, without I/O.
            StatXploreClient(self._api_key, self._base_url, **self._client_kwargs)
            # Cap every read of this instance to a single, fixed point in time.
            self._init_ts = datetime.now(timezone.utc).isoformat()
            self._client: Optional[StatXploreClient] = None
            self._table_requests_used = 0
            self._period_cache: dict = {}

        # The client (requests.Session) is rebuilt lazily after pickling.
        def __getstate__(self):
            state = dict(self.__dict__)
            state["_client"] = None
            return state

        @property
        def client(self) -> StatXploreClient:
            if self._client is None:
                self._client = StatXploreClient(self._api_key, self._base_url, **self._client_kwargs)
            return self._client

        # ------------------------------------------------------------------ resolution

        def list_tables(self) -> list[str]:
            return list(STAT_XPLORE_BUILTIN_TABLES) + [
                n for n in self._registry if n not in STAT_XPLORE_BUILTIN_TABLES
            ]

        def _query_config(self, table_name: str, table_options: dict) -> Optional[StatXploreQueryConfig]:
            """None for built-in tables; a validated config for query tables; else raise."""
            if table_name in STAT_XPLORE_BUILTIN_TABLES:
                return None
            table_options = table_options or {}
            overrides = {
                k: table_options[k] for k in STAT_XPLORE_QUERY_OPTION_KEYS
                if k in table_options and table_options[k] not in (None, "")
            }
            base = self._registry.get(table_name)
            if base is None and "database" not in overrides:
                raise ValueError(
                    f"Unknown Stat-Xplore table '{table_name}'. Use a built-in table "
                    f"{list(STAT_XPLORE_BUILTIN_TABLES)}, a 'table_registry' entry "
                    f"{list(self._registry)}, or supply 'database', 'measures' and "
                    "'dimensions' in the table configuration."
                )
            return stat_xplore_parse_query_config(table_name, {**(base or {}), **overrides})

        def get_table_schema(self, table_name: str, table_options: dict[str, str]) -> StructType:
            config = self._query_config(table_name, table_options)
            if config is None:
                return STAT_XPLORE_BUILTIN_SCHEMAS[table_name]
            return STAT_XPLORE_RESPONSES_SCHEMA if config.output == "responses" else STAT_XPLORE_CELLS_SCHEMA

        def read_table_metadata(self, table_name: str, table_options: dict[str, str]) -> dict:
            config = self._query_config(table_name, table_options)
            if config is None:
                return dict(STAT_XPLORE_BUILTIN_METADATA[table_name])
            key = "response_id" if config.output == "responses" else "record_id"
            if config.incremental:
                return {"primary_keys": [key], "cursor_field": "retrieved_at", "ingestion_type": "cdc"}
            return {"primary_keys": [key], "ingestion_type": "snapshot"}

        def read_table(
            self, table_name: str, start_offset: dict, table_options: dict[str, str]
        ) -> tuple[Iterator[dict], dict]:
            config = self._query_config(table_name, table_options)
            if config is None:
                if table_name == STAT_XPLORE_TABLE_SCHEMA_ITEMS:
                    return iter(self._read_schema_items(table_options or {})), None
                if table_name == STAT_XPLORE_TABLE_INFO:
                    return iter(self._read_info()), None
                return iter(self._read_rate_limit()), None
            if config.incremental:
                return self._read_incremental(config, start_offset or {})
            return iter(self._read_snapshot(config)), None

        # ------------------------------------------------------------------ built-ins

        def _read_schema_items(self, opts: dict) -> list:  # pylint: disable=too-many-locals
            root = (opts.get("schema_root") or _SX_DEFAULT_SCHEMA_ROOT).strip()
            expand = {
                t.strip().upper()
                for t in str(opts.get("schema_expand_types") or _SX_DEFAULT_EXPAND_TYPES).split(",")
                if t.strip()
            }
            max_depth = stat_xplore_int_option(opts.get("schema_max_depth"), "schema_max_depth", 3, 1, 10)
            max_requests = stat_xplore_int_option(
                opts.get("schema_max_requests"), "schema_max_requests", 50, 1, 1000)

            rows: dict = {}
            order: list = []
            queue = [(root, "", 0, None)]
            fetched = 0
            while queue:
                item_id, parent, depth, summary = queue.pop(0)
                if fetched >= max_requests:
                    raise StatXploreResponseError(
                        f"Stat-Xplore schema walk from {root!r} needs more than schema_max_requests="
                        f"{max_requests} requests. Narrow schema_root/schema_expand_types/"
                        "schema_max_depth or raise the limit; nothing was emitted."
                    )
                fetched += 1
                node = self.client.get_schema(None if item_id == _SX_DEFAULT_SCHEMA_ROOT else item_id)
                children = node.get("children") if isinstance(node.get("children"), list) else []
                detail = {k: v for k, v in node.items() if k != "children"}
                self._add_schema_row(rows, order, detail or summary or {"id": item_id}, parent,
                                     depth, True, len(children), root)
                for child in children:
                    if not isinstance(child, dict) or not child.get("id"):
                        raise StatXploreResponseError(f"Stat-Xplore schema item {item_id!r} has a child without 'id'.")
                    ctype = str(child.get("type") or "").upper()
                    if ctype in expand and depth + 1 < max_depth:
                        queue.append((child["id"], node.get("id") or item_id, depth + 1, child))
                    else:
                        self._add_schema_row(rows, order, child, node.get("id") or item_id,
                                             depth + 1, False, None, root)
            return [rows[k] for k in order]

        def _add_schema_row(self, rows, order, item, parent, depth, expanded, child_count, root):  # pylint: disable=too-many-arguments
            key = (item.get("id"), parent)
            if key in rows:
                return
            order.append(key)
            rows[key] = {
                "id": item.get("id"),
                "parent_id": parent,
                "label": item.get("label"),
                "type": item.get("type"),
                "location": item.get("location"),
                "depth": depth,
                "is_expanded": expanded,
                "child_count": child_count,
                "schema_root": root,
                "raw_json": json.dumps(item, sort_keys=True, ensure_ascii=False),
                "retrieved_at": self._init_ts,
            }

        def _read_info(self) -> list:
            info = self.client.get_info()
            languages = info.get("languages")
            if not isinstance(languages, list):
                raise StatXploreResponseError("Stat-Xplore /info response has no 'languages' list.")
            out = []
            for lang in languages:
                if not isinstance(lang, dict) or not lang.get("locale"):
                    raise StatXploreResponseError("Stat-Xplore /info language entry without 'locale'.")
                out.append({
                    "locale": lang["locale"],
                    "display_name": lang.get("displayName"),
                    "raw_json": json.dumps(lang, sort_keys=True, ensure_ascii=False),
                    "retrieved_at": self._init_ts,
                })
            return out

        def _read_rate_limit(self) -> list:
            body = self.client.get_rate_limit()
            return [{
                "scope": "api_key",
                "limit": body.get("limit"),
                "remaining": body.get("remaining"),
                "reset_epoch_ms": body.get("reset"),
                "raw_json": json.dumps(body, sort_keys=True, ensure_ascii=False),
                "retrieved_at": self._init_ts,
            }]

        # ------------------------------------------------------------------ queries

        def _reserve_table_requests(self, count: int, table_name: str) -> None:
            if self._table_requests_used + count > self._max_table_requests:
                raise StatXploreResponseError(
                    f"Stat-Xplore table '{table_name}' needs {count} more /table request(s); this run "
                    f"has used {self._table_requests_used} of max_table_requests_per_run="
                    f"{self._max_table_requests}. Reduce periods / raise period_batch_size, or "
                    "raise the limit. No checkpoint was advanced."
                )

        def _post_table(self, query: dict, table_name: str) -> dict:
            self._reserve_table_requests(1, table_name)
            self._table_requests_used += 1
            return self.client.post_table(query)

        def _discover_periods(self, config: StatXploreQueryConfig) -> list:
            """Ordered time value IDs from the un-recoded time axis (1 request, cached)."""
            key = (config.database, config.measures[0], config.time_field)
            if key in self._period_cache:
                return self._period_cache[key]
            response = self._post_table(config.period_discovery_query(), config.table_name)
            fields = response.get("fields") if isinstance(response, dict) else None
            if not isinstance(fields, list) or len(fields) != 1 or fields[0].get("uri") != config.time_field:
                raise StatXploreResponseError(
                    f"Stat-Xplore period discovery for {config.time_field!r} returned an unexpected "
                    "field list.")
            periods = []
            for item in fields[0].get("items") or []:
                uris = item.get("uris") if isinstance(item, dict) else None
                if not isinstance(uris, list) or len(uris) != 1:
                    raise StatXploreResponseError(
                        f"Stat-Xplore period discovery for {config.time_field!r}: item without a "
                        "single value URI.")
                periods.append(str(uris[0]))
            if not periods:
                raise StatXploreResponseError(f"Stat-Xplore period discovery for {config.time_field!r} returned no periods.")
            if len(set(periods)) != len(periods):
                raise StatXploreResponseError(
                    f"Stat-Xplore period discovery for {config.time_field!r} returned duplicate periods.")
            self._period_cache[key] = periods
            return periods

        def _check_period_coverage(self, config, response, requested: list) -> None:
            for fld in response.get("fields") or []:
                if isinstance(fld, dict) and fld.get("uri") == config.time_field:
                    returned = [u for item in fld.get("items") or [] for u in (item.get("uris") or [])]
                    if sorted(returned) != sorted(requested):
                        missing = sorted(set(requested) - set(returned))
                        raise StatXploreResponseError(
                            f"Stat-Xplore table '{config.table_name}': response did not cover the "
                            f"requested period(s) {missing or requested}; refusing to checkpoint "
                            "an incomplete period.")
                    return
            raise StatXploreResponseError(
                f"Stat-Xplore table '{config.table_name}': response is missing the time field.")

        def _fetch(self, config: StatXploreQueryConfig, periods: Optional[list]) -> list:
            """Execute the query for ``periods`` (None = un-managed single request)."""
            chunks = [None] if periods is None else [
                periods[i:i + config.period_batch_size]
                for i in range(0, len(periods), config.period_batch_size)
            ]
            self._reserve_table_requests(len(chunks), config.table_name)
            records = []
            for chunk in chunks:
                estimate = config.estimated_cells(len(chunk) if chunk is not None else None)
                if estimate is not None and estimate > config.max_cells_per_request:
                    raise StatXploreResponseError(
                        f"Stat-Xplore table '{config.table_name}': request would return ~{estimate} "
                        f"cells (> max_cells_per_request={config.max_cells_per_request}). Not sent.")
                query = config.build_query(chunk)
                response = self._post_table(query, config.table_name)
                if chunk is not None:
                    self._check_period_coverage(config, response, chunk)
                if config.output == "responses":
                    records.append(stat_xplore_response_record(response, config, query, chunk, self._init_ts))
                else:
                    records.extend(stat_xplore_cell_records(response, config, query, self._init_ts))
            return records

        def _select_snapshot_periods(self, config: StatXploreQueryConfig) -> Optional[list]:
            if not config.connector_manages_periods:
                return None
            if config.periods:
                return list(config.periods)
            available = self._discover_periods(config)
            return available[-config.latest_periods:] if config.latest_periods else available

        def _read_snapshot(self, config: StatXploreQueryConfig) -> list:
            return self._fetch(config, self._select_snapshot_periods(config))

        def _read_incremental(  # pylint: disable=too-many-locals
            self, config: StatXploreQueryConfig, start: dict
        ) -> tuple[Iterator[dict], dict]:
            if start.get("query_hash") not in (None, config.query_hash):
                raise ValueError(
                    f"Stat-Xplore table '{config.table_name}': the statistical definition changed "
                    "since the last checkpoint. Run a full refresh of this table.")
            same_cycle = start.get("cycle") == self._init_ts
            if same_cycle and start.get("complete"):
                return iter([]), start

            available = self._discover_periods(config)
            # latest_periods bounds the window (no deep bootstrap); indices stay
            # relative to the full published axis so a new release is not a resync.
            floor = max(0, len(available) - config.latest_periods) if config.latest_periods else 0
            watermark = start.get("watermark")
            wm_idx = -1
            resync = False
            if watermark is not None:
                if watermark not in available:
                    raise StatXploreResponseError(
                        f"Stat-Xplore table '{config.table_name}': checkpointed period {watermark!r} "
                        "is no longer published. Run a full refresh of this table.")
                wm_idx = available.index(watermark)
                stored_idx = start.get("watermark_index")
                resync = stored_idx is not None and stored_idx != wm_idx

            if same_cycle:
                # Continue this run's window exactly where the previous batch
                # stopped - including lookback/resync periods below the watermark.
                first = int(start.get("cursor", wm_idx + 1))
            elif resync:
                # Periods were inserted/removed before the watermark: re-read the window.
                first = 0
            else:
                first = max(0, wm_idx + 1 - config.lookback_periods)
            first = max(first, floor)
            todo = available[first:]
            batch = todo[:config.max_periods_per_batch]
            # Raises on any failure, so neither watermark nor cursor can move
            # past a period whose data was not fully returned.
            records = self._fetch(config, batch) if batch else []

            new_idx = max([wm_idx] + [first + i for i in range(len(batch))])
            offset = {
                "query_hash": config.query_hash,
                "watermark": available[new_idx] if new_idx >= 0 else None,
                "watermark_index": new_idx if new_idx >= 0 else None,
                "cycle": self._init_ts,
                "cursor": first + len(batch),
                "complete": len(batch) == len(todo),
            }
            return iter(records), offset


    ########################################################
    # src/databricks/labs/community_connector/sparkpds/lakeflow_datasource.py
    ########################################################

    LakeflowConnectImpl = StatXploreLakeflowConnect
    # Constant option or column names
    METADATA_TABLE = "_community_table_metadata"
    NAMESPACES_TABLE = "_community_namespaces"
    TABLES_TABLE = "_community_tables"
    VIRTUAL_TABLES = (METADATA_TABLE, NAMESPACES_TABLE, TABLES_TABLE)
    TABLE_NAME = "tableName"
    TABLE_NAME_LIST = "tableNameList"
    TABLE_CONFIGS = "tableConfigs"
    IS_DELETE_FLOW = "isDeleteFlow"
    NAMESPACE_PREFIX = "namespacePrefix"
    NAMESPACE = "namespace"


    def _decode_list_of_str_option(option_name: str, value: str | None) -> list[str] | None:
        """Decode and validate a JSON-encoded ``list[str]`` Spark option.

        Returns ``None`` if the option is absent; otherwise the parsed list.
        Raises ``ValueError`` with the offending value if the JSON is malformed
        or the decoded value is not a list of strings.
        """
        if value is None:
            return None
        try:
            decoded = json.loads(value)
        except json.JSONDecodeError as e:
            raise ValueError(
                f"option '{option_name}' must be a JSON-encoded list[str]; "
                f"got non-JSON value: {value!r}"
            ) from e
        if not isinstance(decoded, list) or not all(isinstance(s, str) for s in decoded):
            raise ValueError(
                f"option '{option_name}' must be a JSON-encoded list[str]; "
                f"got: {decoded!r}"
            )
        return decoded


    def _decode_dict_option(option_name: str, value: str | None) -> dict:
        """Decode and validate a JSON-encoded ``dict`` Spark option."""
        if value is None:
            return {}
        try:
            decoded = json.loads(value)
        except json.JSONDecodeError as e:
            raise ValueError(
                f"option '{option_name}' must be a JSON-encoded dict; "
                f"got non-JSON value: {value!r}"
            ) from e
        if not isinstance(decoded, dict):
            raise ValueError(
                f"option '{option_name}' must be a JSON-encoded dict; got: {decoded!r}"
            )
        return decoded


    # PySpark's DataSource API requires camelCase method names and inherits
    # semantics from the parent class, so per-method docstrings are redundant.
    # pylint: disable=invalid-name,missing-function-docstring
    class LakeflowStreamReader(SimpleDataSourceStreamReader, SupportsTriggerAvailableNow):
        """
        Implements a data source stream reader for Lakeflow Connect.
        Currently, only the simpleStreamReader is implemented, which uses a
        more generic protocol suitable for most data sources that support
        incremental loading.
        """

        def __init__(
            self,
            options: dict[str, str],
            schema: StructType,
            lakeflow_connect: LakeflowConnect,
        ):
            self.options = options
            self.lakeflow_connect = lakeflow_connect
            self.schema = schema

        def initialOffset(self):
            return {}

        def read(self, start: dict) -> (Iterator[tuple], dict):
            is_delete_flow = self.options.get(IS_DELETE_FLOW) == "true"
            # Strip delete flow options before passing to connector
            table_options = {
                k: v for k, v in self.options.items() if k != IS_DELETE_FLOW
            }

            if is_delete_flow:
                records, offset = self.lakeflow_connect.read_table_deletes(
                    self.options[TABLE_NAME], start, table_options
                )
            else:
                records, offset = self.lakeflow_connect.read_table(
                    self.options[TABLE_NAME], start, table_options
                )
            rows = map(lambda x: parse_value(x, self.schema), records)
            return rows, offset

        def readBetweenOffsets(self, start: dict, end: dict) -> Iterator[tuple]:
            # TODO: This does not ensure the records returned are identical across repeated calls.
            # For append-only tables, the data source must guarantee that reading from the same
            # start offset will always yield the same set of records.
            # For tables ingested as incremental CDC, it is only necessary that no new changes
            # are missed in the returned records.
            return self.read(start)[0]

        def prepareForTriggerAvailableNow(self) -> None:
            # No need to do anything special here. Everything is handled in the __init__ method.
            pass


    class LakeflowPartitionedStreamReader(DataSourceStreamReader, SupportsTriggerAvailableNow):
        """Proxy that bridges SupportsPartitionedStream to PySpark's DataSourceStreamReader.

        Used when a connector implements the SupportsPartitionedStream mixin to
        support partitioned streaming reads across Spark executors.
        """

        def __init__(
            self,
            options: dict[str, str],
            schema: StructType,
            lakeflow_connect: LakeflowConnect,
        ):
            self.options = options
            self.schema = schema
            self.lakeflow_connect = lakeflow_connect
            self.table_name = options[TABLE_NAME]
            self.table_options = {k: v for k, v in options.items() if k != IS_DELETE_FLOW}

        def initialOffset(self):
            return {}

        def getDefaultReadLimit(self):
            # Admission control is the connector's responsibility (e.g. via
            # window_days, max_records_per_batch), not the engine's.  Always
            # ask the engine for ReadAllAvailable.
            return ReadAllAvailable()

        def latestOffset(self, start: dict, limit) -> dict:
            # We declared ReadAllAvailable via getDefaultReadLimit; the engine
            # must respect it.  Anything else means admission-control expectations
            # we do not support — fail loudly rather than silently ignore.
            if not isinstance(limit, ReadAllAvailable):
                raise ValueError(
                    f"LakeflowPartitionedStreamReader only supports ReadAllAvailable; "
                    f"got {type(limit).__name__}. Micro-batch sizing must be controlled "
                    f"by the connector implementation (table_options), not the engine."
                )
            return self.lakeflow_connect.latest_offset(
                self.table_name, self.table_options, start
            )

        def partitions(self, start: dict, end: dict):
            partition_descs = self.lakeflow_connect.get_partitions(
                self.table_name, self.table_options, start, end
            )
            return [InputPartition(json.dumps(p)) for p in partition_descs]

        def read(self, partition: InputPartition):
            partition_desc = json.loads(partition.value)
            records = self.lakeflow_connect.read_partition(
                self.table_name, partition_desc, self.table_options
            )
            return map(lambda x: parse_value(x, self.schema), records)

        def prepareForTriggerAvailableNow(self) -> None:
            # No need to do anything special here. Everything is handled in the __init__ method.
            pass


    class LakeflowBatchReader(DataSourceReader):
        def __init__(
            self,
            options: dict[str, str],
            schema: StructType,
            lakeflow_connect: LakeflowConnect,
        ):
            self.options = options
            self.schema = schema
            self.lakeflow_connect = lakeflow_connect
            self.table_name = options[TABLE_NAME]
            self._supports_partition = isinstance(lakeflow_connect, SupportsPartition)

        def partitions(self):
            if self._supports_partition and self.table_name not in VIRTUAL_TABLES:
                try:
                    partition_descs = self.lakeflow_connect.get_partitions(
                        self.table_name, self.options
                    )
                    return [InputPartition(json.dumps(p)) for p in partition_descs]
                except Exception:
                    self._supports_partition = False
            return [InputPartition(None)]

        def read(self, partition):
            if self.table_name == METADATA_TABLE:
                records = self._read_table_metadata()
            elif self.table_name == NAMESPACES_TABLE:
                records = self._read_namespaces()
            elif self.table_name == TABLES_TABLE:
                records = self._read_tables()
            elif self._supports_partition and partition.value is not None:
                partition_desc = json.loads(partition.value)
                records = self.lakeflow_connect.read_partition(
                    self.table_name, partition_desc, self.options
                )
            else:
                records, _ = self.lakeflow_connect.read_table(self.table_name, None, self.options)
            return map(lambda x: parse_value(x, self.schema), records)

        def _read_table_metadata(self):
            table_names = _decode_list_of_str_option(
                TABLE_NAME_LIST, self.options.get(TABLE_NAME_LIST)
            ) or []
            table_configs = _decode_dict_option(
                TABLE_CONFIGS, self.options.get(TABLE_CONFIGS)
            )
            all_records = []
            # Preserve caller-supplied table order — caller controls it.
            for table in table_names:
                metadata = self.lakeflow_connect.read_table_metadata(
                    table, table_configs.get(table, {})
                )
                all_records.append({TABLE_NAME: table, **metadata})
            return all_records

        def _read_namespaces(self):
            # Connectors without SupportsNamespaces are flat — no rows.
            if not isinstance(self.lakeflow_connect, SupportsNamespaces):
                return []
            prefix = _decode_list_of_str_option(
                NAMESPACE_PREFIX, self.options.get(NAMESPACE_PREFIX)
            )
            namespaces = self.lakeflow_connect.list_namespaces(prefix)
            # Sort framework-side for deterministic output regardless of
            # connector iteration order.
            return [{"namespace": ns} for ns in sorted(namespaces)]

        def _read_tables(self):
            namespace_supplied = NAMESPACE in self.options
            if isinstance(self.lakeflow_connect, SupportsNamespaces):
                if not namespace_supplied:
                    raise ValueError(
                        f"option '{NAMESPACE}' is required when reading "
                        f"'{TABLES_TABLE}' against a connector that implements "
                        f"SupportsNamespaces. Pass a JSON-encoded list[str] "
                        f"(use '[]' for root-level tables; walk the tree via "
                        f"'{NAMESPACES_TABLE}' to enumerate every namespace)."
                    )
                namespace = _decode_list_of_str_option(
                    NAMESPACE, self.options[NAMESPACE]
                )
                tables = self.lakeflow_connect.list_tables_in_namespace(namespace)
                return [
                    {"namespace": namespace, TABLE_NAME: tn}
                    for tn in sorted(tables)
                ]
            # Flat connector path. Reject a stray `namespace` option — the
            # caller probably mistook this connector for namespace-aware and
            # silently ignoring the option would mask the bug.
            if namespace_supplied:
                raise ValueError(
                    f"option '{NAMESPACE}' was supplied but the connector does "
                    f"not implement SupportsNamespaces. Either omit the option "
                    f"or use a namespace-aware connector."
                )
            return [
                {"namespace": [], TABLE_NAME: tn}
                for tn in sorted(self.lakeflow_connect.list_tables())
            ]


    class LakeflowSource(DataSource):
        """
        PySpark DataSource base for Lakeflow Connect.

        Two ways the connector implementation is bound:

        - Per-source subclass (wheel / multi-file deployment): subclass and set
          ``_lakeflow_connect_cls``::

              class GmailDataSource(LakeflowSource):
                  _lakeflow_connect_cls = GmailLakeflowConnect

              spark.dataSource.register(GmailDataSource)

        - Merged single-file deployment (SDP): ``_lakeflow_connect_cls`` is left
          ``None`` and the connector is taken from the module-level
          ``LakeflowConnectImpl`` placeholder, which the merge script substitutes
          with the actual implementation class.
        """

        # Per-source subclasses set this. Left ``None`` on the base so the merged
        # single-file path falls back to the ``LakeflowConnectImpl`` placeholder.
        _lakeflow_connect_cls = None

        # Spark format name. Defaults to "lakeflow_connect" because Unity Catalog
        # connection-option injection looks for that exact string. A per-source
        # subclass may override this with its source name once it no longer relies
        # on UC injection (see the commented override in each source's __init__.py).
        _format_name = "lakeflow_connect"

        def __init__(self, options):
            self.options = options
            table = options.get(TABLE_NAME)
            # Catch typos against the framework's reserved virtual-table namespace
            # early — falling through to the connector with an unknown
            # `_community_*` name yields a confusing per-connector error.
            if table and table.startswith("_community_") and table not in VIRTUAL_TABLES:
                raise ValueError(
                    f"unknown framework virtual table '{table}'. Valid framework "
                    f"virtual tables are: {', '.join(VIRTUAL_TABLES)}. "
                    f"For a regular source table, use a name that does not start "
                    f"with '_community_'."
                )
            # Per-source subclasses bind the implementation via _lakeflow_connect_cls.
            # The merged single-file path leaves it None and relies on the
            # LakeflowConnectImpl placeholder (substituted by the merge script).
            connect_cls = type(self)._lakeflow_connect_cls or LakeflowConnectImpl
            self.lakeflow_connect = connect_cls(options)  # pylint: disable=abstract-class-instantiated

        @classmethod
        def name(cls):
            return cls._format_name

        def schema(self):
            table = self.options[TABLE_NAME]
            if table == METADATA_TABLE:
                return StructType(
                    [
                        StructField(TABLE_NAME, StringType(), False),
                        StructField("primary_keys", ArrayType(StringType()), True),
                        StructField("cursor_field", StringType(), True),
                        StructField("ingestion_type", StringType(), True),
                    ]
                )
            if table == NAMESPACES_TABLE:
                return StructType(
                    [
                        StructField("namespace", ArrayType(StringType()), False),
                    ]
                )
            if table == TABLES_TABLE:
                return StructType(
                    [
                        StructField("namespace", ArrayType(StringType()), False),
                        StructField(TABLE_NAME, StringType(), False),
                    ]
                )
            return self.lakeflow_connect.get_table_schema(table, self.options)

        def reader(self, schema: StructType):
            return LakeflowBatchReader(self.options, schema, self.lakeflow_connect)

        def streamReader(self, schema: StructType):
            # Use the partitioned DataSourceStreamReader when the connector
            # implements SupportsPartitionedStream and the table opts in.
            # Otherwise, delegate to super() which raises PySparkNotImplementedError,
            # causing Spark to fall back to simpleStreamReader().
            if isinstance(self.lakeflow_connect, SupportsPartitionedStream):
                table = self.options[TABLE_NAME]
                if self.lakeflow_connect.is_partitioned(table):
                    return LakeflowPartitionedStreamReader(self.options, schema, self.lakeflow_connect)
            return super().streamReader(schema)

        def simpleStreamReader(self, schema: StructType):
            return LakeflowStreamReader(self.options, schema, self.lakeflow_connect)


    spark.dataSource.register(LakeflowSource)
